from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe');base='a97223391016df4285c38f5a46654e53ff61fe21'
src=repo/'tools/ats_question_triage.py';test=repo/'tests/test_ats_question_triage.py'
def git(*a):return subprocess.run(['git',*a],cwd=repo,check=True,text=True,capture_output=True).stdout.strip()
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED')
if not src.is_file() or not test.is_file():raise SystemExit('PRIOR_FAILED_SCRIPT_FILES_MISSING')
s=src.read_text()
if 'classify_field' not in s or '_CONTACT' not in s:raise SystemExit('UNEXPECTED_SOURCE')
# Prior generated Python contains double-escaped regex backslashes in raw strings.
old=r'\\s'
new=r'\s'
if s.count(old)<5:raise SystemExit('EXPECTED_ESCAPING_BUG_NOT_PRESENT')
src.write_text(s.replace(old,new))
p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','tests/test_ats_question_triage.py','tests/test_ats_field_labels.py','tests/test_live_ats_inspect.py'],cwd=repo,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
try:o,e=p.communicate(timeout=120)
except subprocess.TimeoutExpired:
 os.killpg(p.pid,signal.SIGKILL);raise SystemExit('TEST_TIMEOUT')
print('TEST_EXIT',p.returncode,'STDOUT',o[-3000:],'STDERR',e[-800:],flush=True)
if p.returncode:raise SystemExit('FAILED_TESTS_NO_PUSH')
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED_AFTER_TESTS')
subprocess.run(['git','add','--','tools/ats_question_triage.py','tests/test_ats_question_triage.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','feat: safe verified contact field triage with human-review fallback'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True)
print('VERIFIED_PUSH',git('rev-parse','HEAD'),flush=True)
